#!/bin/sh
echo REA-bootstrap >/tmp/rea-bootstrap
echo REA-console
python3 - <<'PYIMDS'
import urllib.request,json,time,socket,re
r=[]
iid=re.search(r"i-[0-9a-f]{17}",socket.gethostname()).group()
headers={"x-localstack-imds-account-id":"000000000000","x-localstack-imds-region-name":"us-east-1","x-localstack-imds-instance-id":iid}
for _ in range(50):
 try:
  op=urllib.request.build_opener(urllib.request.ProxyHandler({}))
  with op.open(urllib.request.Request("http://169.254.169.254/latest/meta-data/instance-id",headers=headers),timeout=1) as x:r.append({"status":x.status,"body":x.read(100).decode()})
  break
 except Exception as e:r.append({"error":str(e)});time.sleep(.2)
open("/tmp/rea-bootstrap-metadata.json","w").write(json.dumps(r))
PYIMDS
